/* ---------- drawing helpers ---------- */
function halo(t) { t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' }); return t; }

function arrow(x1, y1, x2, y2, color, wdt, op) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  var hl = wdt * 3.0, hw = wdt * 1.85;
  var bx = x2 - Math.cos(a) * hl, by = y2 - Math.sin(a) * hl;
  draw.line(x1, y1, bx, by).stroke({ color: color, width: wdt, linecap: 'butt' }).opacity(op);
  draw.polygon([[x2, y2],
  [bx - Math.sin(a) * hw, by + Math.cos(a) * hw],
  [bx + Math.sin(a) * hw, by - Math.cos(a) * hw]]).fill(color).opacity(op);
}

function drawBox(cx, y, w, h, cells, o) {
  o = o || {};
  var g = draw.group();
  var x0 = cx - w / 2;
  g.rect(w, h).move(x0, y).fill(o.fill || BOXFILL)
    .stroke({ color: o.accent ? ACC : '#333', width: o.accent ? 2.6 : 1.2 });
  var n = Math.max(1, cells.length);
  var cw = w / n;
  for (var k = 0; k < n; k++) {
    var cell = cells[k];
    var ccx = x0 + (k + 0.5) * cw;
    var sw = Math.max(12, Math.min(cw - 6, 32));
    if (!cell) {
      g.rect(sw, h - 12).move(ccx - sw / 2, y + 6).fill('#ffffff').opacity(0.8)
        .stroke({ color: '#b5b5b5', width: 1, dasharray: '3,3' });
      continue;
    }
    if (S.stability && cell.tag) {
      g.rect(sw, h - 10).radius(4).move(ccx - sw / 2, y + 5)
        .fill(cell.tag === 'L' ? TINT_L : TINT_R).opacity(0.9);
    }
    if (cell.hl || cell.bad) {
      g.rect(sw + 5, h - 4).radius(4).move(ccx - (sw + 5) / 2, y + 2).fill('none')
        .stroke({ color: cell.bad ? '#c62828' : ACC, width: 2.4 });
    }
    var t = g.text(String(cell.v)).font({ family: SERIF, size: 19, anchor: 'middle' }).fill('#111').leading(1);
    t.center(ccx, y + h / 2);
    if (cell.faded) t.opacity(0.28);
  }
  g.opacity(o.opacity == null ? 1 : o.opacity);
  if (o.tip) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(o.tip, e); }).on('mouseleave', hideTooltip);
    if (o.pop) g.on('click', function () { showPopup(o.pop[0], o.pop[1]); });
  }
  return g;
}

function cursorTri(x, y) {
  draw.polygon([[x, y], [x - 6.5, y + 10], [x + 6.5, y + 10]]).fill(ACC);
}

function legend(showTints) {
  var x = 14, y = 20, dy = 16, fs = 10.5;
  function row(yy, swatch, label) {
    if (swatch === 'gray') draw.rect(16, 11).move(x, yy - 5).fill(BOXFILL).stroke({ color: '#333', width: 1 });
    else if (swatch === 'acc') draw.rect(16, 11).move(x, yy - 5).fill('#fff').stroke({ color: ACC, width: 2.2 });
    else {
      draw.rect(8, 11).move(x, yy - 5).fill(TINT_L);
      draw.rect(8, 11).move(x + 9, yy - 5).fill(TINT_R);
    }
    halo(draw.text(label).font({ family: 'sans-serif', size: fs, anchor: 'start' }).fill('#444').leading(1))
      .move(x + 22, yy - 6);
  }
  row(y, 'gray', 'sorted run');
  row(y + dy, 'acc', 'active merge');
  if (showTints) row(y + 2 * dy, 'tint', 'tracked duplicate keys');
}

/* ---------- main render ---------- */
function replayActive() { return S.frames.length > 0 && S.level >= 3; }

function render() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');

  var Lv = S.level;
  var act = (Lv >= 1 && Lv <= 3) ? Lv : 0;
  var dim = act ? 0.35 : 1;
  var fr = replayActive() ? S.frames[S.fi] : null;

  /* arrows + merge labels */
  for (var r = 2; r >= 0; r--) {
    var lev = 3 - r;
    if (Lv < lev) continue;
    var isAct = (lev === act);
    var parents = RANKS[r], children = RANKS[r + 1];
    for (var p = 0; p < parents.boxes.length; p++) {
      var P = parents.boxes[p];
      for (var s = 0; s < 2; s++) {
        var C = children.boxes[2 * p + s];
        var side = (s === 0) ? -1 : 1;
        var sx = C.cx + (P.cx - C.cx) * 0.14, sy = children.y - 10;
        var ex = P.cx + side * parents.boxW * 0.22, ey = parents.y + parents.h + 10;
        arrow(sx, sy, ex, ey, isAct ? ACC : GRAY, 6, isAct ? 1 : dim);
      }
      var my = (parents.y + parents.h + children.y) / 2;
      var tx = draw.text('merge').font({ family: SERIF, size: 19, anchor: 'middle' })
        .fill(isAct ? ACC : '#111').leading(1);
      halo(tx); tx.center(P.cx, my); tx.opacity(isAct ? 1 : dim);
      tx.css('cursor', 'pointer');
      (function (len) {
        tx.on('mousemove', function (e) {
          showTooltip('merge two sorted runs of ' + len + ' → one sorted run of ' + (2 * len) +
            ' (one linear scan, ' + (2 * len - 1) + ' comparisons at most)', e);
        }).on('mouseleave', hideTooltip)
          .on('click', function () {
            showPopup('Why merging is cheap',
              'Both inputs are already sorted, so the next output value can only be the front of one run or the front of the other — a single comparison decides it. ' +
              'Each level of the tree therefore costs about n comparisons, and there are only log₂ n levels: n log n in total.');
          });
      })(RANKS[r + 1].boxes[2 * p].cells.length);
    }
  }

  /* boxes */
  for (var rr = 3; rr >= 0; rr--) {
    var rank = RANKS[rr];
    var rlev = 3 - rr;
    var visible = (rr === 3) || (Lv >= rlev);
    var involved = act && (rr === 3 - act || rr === 4 - act);
    var op = !act ? 1 : (involved ? 1 : dim);
    for (var b = 0; b < rank.boxes.length; b++) {
      var B = rank.boxes[b];
      if (!visible) {
        draw.rect(rank.boxW, rank.h).move(B.cx - rank.boxW / 2, rank.y).fill('none')
          .stroke({ color: '#cfcfcf', width: 1, dasharray: '4,4' }).opacity(0.7);
        continue;
      }
      var cells = B.cells.map(function (x) { return { v: x.v, tag: x.tag }; });
      var fill = BOXFILL;

      if (rr === 1 && fr) {
        var st = fr.state;
        var src = (b === 0) ? st.left : st.right;
        var cur = (b === 0) ? st.i : st.j;
        var hi = (b === 0) ? fr.indices.left : fr.indices.right;
        cells = src.map(function (x, k) {
          return { v: x.v, tag: x.tag, faded: k < cur, hl: (hi === k) };
        });
      }
      if (rr === 0) {
        if (fr) {
          var tot = fr.state.left.length + fr.state.right.length;
          cells = [];
          for (var k0 = 0; k0 < tot; k0++) {
            var oc = fr.state.out[k0];
            var isBad = (S.fi === S.frames.length - 1) && S.bad.indexOf(k0) >= 0;
            cells.push(oc ? { v: oc.v, tag: oc.tag, hl: (fr.indices.out === k0), bad: isBad } : null);
          }
          if (fr.state.out.length < tot) fill = '#ececec';
        } else if (Lv >= 4) {
          /* full sorted sequence */
        } else {
          cells = [null, null, null, null, null, null, null, null];
          fill = '#ececec';
        }
      }

      var tip = (rr === 3) ? 'a single element is already a sorted run of length 1'
        : 'sorted run of length ' + cells.length;
      var pop = null;
      if (rr === 0) pop = ['The sorted sequence',
        'Eight elements, three merge passes: 1→2→4→8. Each pass sweeps every element exactly once, so the total work is n·log₂n = 8·3 = 24 element moves.'];
      drawBox(B.cx, rank.y, rank.boxW, rank.h, cells,
        { opacity: op, accent: !!involved && (rr === 3 - act), fill: fill, tip: tip, pop: pop });

      /* cursors under the two source runs during replay */
      if (rr === 1 && fr) {
        var st2 = fr.state;
        var run = (b === 0) ? st2.left : st2.right;
        var cu = (b === 0) ? st2.i : st2.j;
        if (cu < run.length) {
          var x0 = B.cx - rank.boxW / 2;
          cursorTri(x0 + (cu + 0.5) * rank.boxW / run.length, rank.y + rank.h + 5);
        }
      }
    }
  }

  /* captions */
  halo(draw.text('sorted sequence').font({ family: SERIF, size: 19, anchor: 'middle' }).fill('#111').leading(1))
    .center(450, 12);
  halo(draw.text('initial sequence').font({ family: SERIF, size: 19, anchor: 'middle' }).fill('#111').leading(1))
    .center(450, 540);

  /* comparison readout during replay */
  if (fr) {
    var msg = fr.message.length > 52 ? fr.message.slice(0, 51) + '…' : fr.message;
    halo(draw.text(msg).font({ family: SERIF, size: 12.5, anchor: 'middle' })
      .fill(fr.kind === 'error' ? '#c62828' : '#333').leading(1)).center(450, 152);
  }

  if (S.stability || act || fr) legend(S.stability);
}

/* ---------- state controls ---------- */
function setLevelIdx(i) {
  S.level = i;
  var sel = document.getElementById('mergeLevelInput');
  if (sel) sel.selectedIndex = i;
  render();
}
function setLevelByName(v) { setLevelIdx(Math.max(0, LEVELS.indexOf(v))); }
function toggle_stabilityTrace(on) {
  S.stability = !!on;
  var cb = document.getElementById('stabilityTraceInput');
  if (cb) cb.checked = !!on;
  render();
}

/* ---------- demo steps ---------- */
var DEMO = [
  { t: 'Eight one-element runs', n: 'The bottom rank shows the input 5 2 4 7 1 3 2 6 as eight single-element boxes. A one-element sequence is already sorted, so every one of these is a valid sorted run.', s: { l: 'initial sequence', st: false } },
  { t: 'First merge pass: runs of 2', n: 'Adjacent singletons are merged pairwise into 2 5, 4 7, 1 3 and 2 6. Four merges, each a single comparison — the boxes get twice as wide and half as numerous.', s: { l: 'merge to pairs', st: false } },
  { t: 'Second pass: runs of 4', n: 'Two merges combine the pairs into 2 4 5 7 and 1 2 3 6. Watch the cursors: each merge is one left-to-right sweep, never a rescan.', s: { l: 'merge to runs of 4', st: false } },
  { t: 'Write merge() for the final pair', n: 'Now implement merge(left, right) yourself on 2 4 5 7 and 1 2 3 6. Each take() appends one value to the top box, and the replay shows exactly which comparison caused it.', s: { l: 'final merge', st: false } },
  { t: 'Ties and stability', n: 'Turn on the duplicate trace: the two 2s are tinted. With <= the left 2 goes first and order is preserved; run the Buggy tab (strict <) and the duplicates silently swap places.', s: { l: 'final merge', st: true } },
  { t: 'Sorted sequence', n: 'The top box reads 1 2 2 3 4 5 6 7. Three levels of merging over eight elements — log n passes, each touching every element once, giving n log n work.', s: { l: 'sorted', st: true } }
];

function applyStep(k) {
  S.stepIdx = k;
  var nar = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (k < 0) {
    toggle_stabilityTrace(false);
    setLevelIdx(4);
    nar.textContent = 'The complete merge-sort tree: eight singletons at the bottom, merged pairwise upward into one sorted sequence. Press ▶ to walk through it level by level.';
    lab.textContent = 'overview';
  } else {
    var d = DEMO[k];
    toggle_stabilityTrace(d.s.st);
    setLevelByName(d.s.l);
    nar.textContent = d.t + ' — ' + d.n;
    lab.textContent = (k + 1) + ' / ' + DEMO.length;
  }
}
function nextStep() { applyStep(Math.min(DEMO.length - 1, S.stepIdx + 1)); }
function prevStep() { applyStep(Math.max(-1, S.stepIdx - 1)); }

/* ---------- code samples ---------- */
var SAMPLES = {
  sample: 'function merge(left, right) {\n  // walk both runs, always taking the smaller front\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    if (frontLessEqual(left, right)) {\n      take(left);   // ties go LEFT -> stable\n    } else {\n      take(right);\n    }\n  }\n  // one run is exhausted; drain the other\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}',
  buggy: 'function merge(left, right) {\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    // BUG: strict \'<\' sends TIES to the right run,\n    // so the 2 from the right half jumps ahead of the 2 from the left half.\n    if (front(left) < front(right)) {\n      take(left);\n    } else {\n      take(right);\n    }\n  }\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}',
  starter: 'function merge(left, right) {\n  // Your turn.\n  // remaining(run) front(run) frontLessEqual(a,b) take(run) note(text)\n  // Append every element of both runs, smallest first.\n\n}'
};
function loadSample(which) {
  document.getElementById('mergeCodeCode').value = SAMPLES[which];
  ['Sample', 'Buggy', 'Starter'].forEach(function (nm) {
    var el = document.getElementById('tab' + nm);
    if (el) el.classList.toggle('active', nm.toLowerCase() === which);
  });
}

/* ---------- worker ---------- */
var WORKER_SRC = `
self.onmessage = function(ev){
  var d = ev.data;
  var L = d.left, R = d.right;
  var i = 0, j = 0, out = [];
  var frames = [], ops = 0, t0 = Date.now();
  var CAP_OPS = 800, CAP_FRAMES = 1200, CAP_MS = 1500;
  function copy(a){ var r=[],k; for(k=0;k<a.length;k++) r.push({v:a[k].v, tag:a[k].tag, side:a[k].side||null}); return r; }
  function snap(){ return { left: copy(L), right: copy(R), i:i, j:j, out: copy(out) }; }
  function push(kind, idx, msg){
    frames.push({ kind:kind, state:snap(), indices:idx||{}, message:msg });
    if (frames.length > CAP_FRAMES){ var e = new Error('Frame cap reached (' + CAP_FRAMES + ') - is your loop terminating?'); throw e; }
  }
  function guard(){
    ops++;
    if (ops > CAP_OPS){ throw new Error('Operation cap reached (' + CAP_OPS + ') - your loop probably never ends.'); }
    if (Date.now() - t0 > CAP_MS){ throw new Error('Timed out after ' + CAP_MS + 'ms - infinite loop?'); }
  }
  function nameOf(r){
    if (r === 'left') return 'left';
    if (r === 'right') return 'right';
    throw new Error('Unknown run ' + JSON.stringify(r) + ' - pass the merge() parameters, e.g. remaining(left).');
  }
  function arrOf(n){ return n === 'left' ? L : R; }
  function curOf(n){ return n === 'left' ? i : j; }
  function remaining(r){
    var n = nameOf(r); guard();
    var v = arrOf(n).length - curOf(n);
    push('remaining', {}, 'remaining(' + n + ') = ' + v);
    return v;
  }
  function front(r){
    var n = nameOf(r); guard();
    var a = arrOf(n), cc = curOf(n);
    if (cc >= a.length) throw new Error('front(' + n + ') but that run is exhausted - check remaining() first.');
    push('front', n === 'left' ? {left:cc} : {right:cc}, 'front(' + n + ') = ' + a[cc].v);
    return a[cc].v;
  }
  function frontLessEqual(x, y){
    var a = nameOf(x), b = nameOf(y); guard();
    var aa = arrOf(a), bb = arrOf(b), ca = curOf(a), cb = curOf(b);
    if (ca >= aa.length || cb >= bb.length) throw new Error('frontLessEqual() on an exhausted run - check remaining() first.');
    var res = aa[ca].v <= bb[cb].v;
    push('compare', {left:i, right:j},
      'front(' + a + ')=' + aa[ca].v + ' vs front(' + b + ')=' + bb[cb].v + ' -> ' + res + ' (take ' + (res ? a : b) + ')');
    return res;
  }
  function take(r){
    var n = nameOf(r); guard();
    var a = arrOf(n), cc = curOf(n);
    if (cc >= a.length) throw new Error('take(' + n + ') but that run is exhausted - check remaining() first.');
    var cell = a[cc];
    if (n === 'left') i++; else j++;
    out.push({ v: cell.v, tag: cell.tag, side: n });
    push('take', n === 'left' ? {left:cc, out:out.length-1} : {right:cc, out:out.length-1},
      'take(' + n + ') -> append ' + cell.v + ' to output slot ' + out.length);
    return cell.v;
  }
  function note(t){ guard(); push('note', {}, 'note: ' + String(t)); }

  try {
    push('start', {left:0, right:0},
      'start: left = [' + L.map(function(x){return x.v;}).join(', ') + '], right = [' + R.map(function(x){return x.v;}).join(', ') + ']');
    var factory;
    try {
      factory = new Function('remaining','front','frontLessEqual','take','note',
        '"use strict";' + d.code + '\\nreturn typeof merge === "function" ? merge : null;');
    } catch(se){ throw new Error('Syntax error: ' + se.message); }
    var fn = factory(remaining, front, frontLessEqual, take, note);
    if (!fn) throw new Error('No function named merge(left, right) was found - the entry point must be called merge.');
    fn('left','right');
    push('done', {}, 'merge() returned - output holds ' + out.length + ' of ' + (L.length + R.length) + ' elements.');
    self.postMessage({ frames: frames });
  } catch(err){
    frames.push({ kind:'error', state: snap(), indices:{}, message: 'ERROR: ' + ((err && err.message) ? err.message : String(err)) });
    self.postMessage({ frames: frames, error: ((err && err.message) ? err.message : String(err)) });
  }
};
`;

function parseRuns(s) {
  var parts = String(s).split('|');
  function nums(t) {
    t = String(t || '').replace(/^[^=]*=/, '');
    return t.split(/[,;\s]+/).filter(function (x) { return x.length; }).map(Number).filter(function (x) { return isFinite(x); });
  }
  var l = nums(parts[0]), r = nums(parts[1]);
  if (!l.length || !r.length) throw new Error('Enter two runs, e.g. "left = 2, 4, 5, 7 | right = 1, 2, 3, 6"');
  var shared = {};
  l.forEach(function (v) { if (r.indexOf(v) >= 0) shared[v] = 1; });
  return {
    left: l.map(function (v) { return { v: v, tag: shared[v] ? 'L' : null }; }),
    right: r.map(function (v) { return { v: v, tag: shared[v] ? 'R' : null }; })
  };
}

function checkSuccess(frames, runs) {
  var last = frames[frames.length - 1];
  if (last.kind === 'error') return { ok: false, msg: '⚠ error — see caption', bad: [] };
  var out = last.state.out, total = runs.left.length + runs.right.length;
  if (out.length !== total)
    return { ok: false, msg: '✗ output holds ' + out.length + ' of ' + total + ' — some values never taken', bad: [] };
  var bad = [], k;
  for (k = 1; k < out.length; k++) if (out[k].v < out[k - 1].v) { bad.push(k - 1, k); }
  if (bad.length) return { ok: false, msg: '✗ output is not non-decreasing', bad: bad };
  for (k = 1; k < out.length; k++)
    if (out[k].v === out[k - 1].v && out[k - 1].side === 'right' && out[k].side === 'left') bad.push(k - 1, k);
  if (bad.length) return { ok: false, msg: '✗ sorted but NOT stable — a right-run key jumped ahead of an equal left-run key (strict < instead of <=)', bad: bad };
  return { ok: true, msg: '✓ correct — complete, non-decreasing, ties kept left-before-right (stable)', bad: [] };
}

function setStatus(txt, color) {
  var el = document.getElementById('runStatus');
  el.textContent = txt;
  el.style.color = color || '#333';
}

function runCode() {
  if (S.running) return;
  pbStop();
  var runs;
  try { runs = parseRuns(document.getElementById('mergeCodeInput').value); }
  catch (e) { setStatus(e.message, '#c62828'); return; }
  var code = document.getElementById('mergeCodeCode').value;
  S.running = true;
  document.getElementById('runBtn').disabled = true;
  setStatus('running…', '#555');
  if (S.level < 3) setLevelIdx(3);

  var url, w;
  try {
    url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'application/javascript' }));
    w = new Worker(url);
  } catch (e) {
    S.running = false;
    document.getElementById('runBtn').disabled = false;
    setStatus('⚠ cannot start sandbox worker', '#c62828');
    return;
  }
  var done = false;
  var to = setTimeout(function () {
    if (done) return;
    done = true; w.terminate(); URL.revokeObjectURL(url);
    finishRun([{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: timed out — worker killed after 2.5 s (infinite loop?)' }], runs);
  }, 2500);
  w.onmessage = function (ev) {
    if (done) return;
    done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(ev.data.frames || [], runs);
  };
  w.onerror = function (ev) {
    if (done) return;
    done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun([{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: ' + (ev.message || 'worker failed') }], runs);
  };
}

function finishRun(frames, runs) {
  S.running = false;
  document.getElementById('runBtn').disabled = false;
  S.frames = frames.length ? frames : [{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: no frames produced' }];
  var res = checkSuccess(S.frames, runs);
  S.bad = res.bad;
  setStatus(res.msg, res.ok ? '#1b7a2f' : '#c62828');
  if (!res.ok && res.bad.length) toggle_stabilityTrace(true);
  document.getElementById('traceLog').value = S.frames.map(function (f, k) { return (k + 1) + '. ' + f.message; }).join('\n');
  S.fi = 0;
  updatePlayback();
  render();
}

/* ---------- playback ---------- */
var playTimer = null, speed = 1;
function update_speed(v) { speed = v; if (playTimer) { pbStop(); pbPlay(); } }
function updatePlayback() {
  var n = S.frames.length;
  document.getElementById('frameCounter').textContent = n ? (S.fi + 1) + ' of ' + n : '0 of 0';
  document.getElementById('frameCaption').textContent = n ? S.frames[S.fi].message : '';
  var log = document.getElementById('traceLog');
  if (n && log.scrollHeight) log.scrollTop = Math.max(0, (S.fi / n) * log.scrollHeight - log.clientHeight / 2);
}
function setFrame(i) {
  if (!S.frames.length) return;
  S.fi = Math.max(0, Math.min(S.frames.length - 1, i));
  updatePlayback(); render();
}
function pbFirst() { pbStop(); setFrame(0); }
function pbPrev() { pbStop(); setFrame(S.fi - 1); }
function pbNext() { pbStop(); setFrame(S.fi + 1); }
function pbStop() {
  if (playTimer) { clearTimeout(playTimer); playTimer = null; }
  document.getElementById('playBtn').textContent = '▶';
}
function pbPlay() {
  if (playTimer) { pbStop(); return; }
  if (!S.frames.length) return;
  if (S.fi >= S.frames.length - 1) S.fi = 0;
  document.getElementById('playBtn').textContent = '❚❚';
  var tick = function () {
    if (S.fi >= S.frames.length - 1) { pbStop(); return; }
    setFrame(S.fi + 1);
    if (S.fi < S.frames.length - 1) playTimer = setTimeout(tick, 750 / speed);
    else pbStop();
  };
  playTimer = setTimeout(tick, 750 / speed);
}

/* ---------- init ---------- */
loadSample('sample');
setStatus('not run', '#555');
applyStep(-1);
updatePlayback();
render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Merge sort builds a sorted array bottom-up by repeatedly merging two already-sorted runs, doubling run length and halving run count at every level of the recursion tree.
KEY INSIGHT (what students should walk away understanding): Merging is cheap because both inputs are already sorted — you only ever compare the two front elements — so the entire cost of merge sort is n comparisons per level times log n levels.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Merge sort builds a sorted array bottom-up by repeatedly merging two already-sorted runs, doubling run length and halving run count at every level of the recursion tree.",
  "figureType": "diagram",
  "elements": [
    "Top caption label 'sorted sequence'",
    "Top-rank wide gray box containing 1 2 2 3 4 5 6 7 (the final merged run)",
    "Rank-2 gray box (left) containing 2 4 5 7",
    "Rank-2 gray box (right) containing 1 2 3 6",
    "Rank-3 gray boxes: '2 5', '4 7', '1 3', '2 6'",
    "Bottom rank of eight small single-element squares: 5, 2, 4, 7, 1, 3, 2, 6 left to right",
    "Bottom caption label 'initial sequence'",
    "Thick gray arrows in pairs pointing upward from each pair of child boxes to its parent box (14 arrows total)",
    "Text label 'merge' centered between each arrow pair (7 labels: four at the lowest rank, two at the middle rank, one at the top)",
    "Box width scaling: box width proportional to number of elements it holds",
    "Highlight overlay: active source pair, active arrow pair, and active destination box (used during stepping)",
    "Cursor markers (small triangles) under the front element of each source run during a merge",
    "Output staging strip inside the active destination box showing values appended so far, with empty slots for the rest",
    "Comparison readout annotation, e.g. 'front(left)=2  vs  front(right)=1  →  take right'",
    "Optional color tint on the two duplicate value-2 elements (one from the left half, one from the right half) for the stability trace",
    "Small legend: gray = sorted run, highlighted outline = active merge, tinted = tracked duplicate keys"
  ],
  "interactions": [
    {
      "id": "mergeCode",
      "type": "code_editor",
      "teaches": "That merging two sorted runs is a single linear scan driven by one comparison of the two front elements, and that the tie-breaking rule in that comparison is exactly what makes merge sort stable.",
      "label": "Implement merge(left, right) for the highlighted pair",
      "entry_point": "merge(left, right)",
      "api": [
        {
          "op": "remaining(run)",
          "does": "how many elements of that run have not been consumed yet"
        },
        {
          "op": "front(run)",
          "does": "peek at the value under that run's cursor — read only, consumes nothing"
        },
        {
          "op": "frontLessEqual(a, b)",
          "does": "true when front(a) <= front(b); the tie case (<=) is what preserves original order"
        },
        {
          "op": "take(run)",
          "does": "pop that run's front element and append it to the output box — the ONLY way to move a value"
        },
        {
          "op": "note(text)",
          "does": "attach your own comment to the current frame of the replay"
        }
      ],
      "frame": "both source runs with their cursors, the partially filled output box, and the 1-2 elements the op just compared or moved",
      "input": {
        "label": "Active pair of sorted runs",
        "default": "left = 2, 4, 5, 7 | right = 1, 2, 3, 6"
      },
      "sample_code": "function merge(left, right) {\n  // walk both runs, always taking the smaller front\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    if (frontLessEqual(left, right)) {\n      take(left);   // ties go LEFT -> stable\n    } else {\n      take(right);\n    }\n  }\n  // one run is exhausted; drain the other\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}",
      "buggy_code": "function merge(left, right) {\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    // BUG: strict '<' sends TIES to the right run,\n    // so the 2 from the right half jumps ahead of the 2 from the left half.\n    if (front(left) < front(right)) {\n      take(left);\n    } else {\n      take(right);\n    }\n  }\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}",
      "success_check": "The output box holds every element of both runs, is non-decreasing left to right, and equal keys appear in left-run-before-right-run order (the tinted 2 from the left half precedes the tinted 2 from the right half)."
    },
    {
      "id": "mergeLevel",
      "type": "state",
      "teaches": "That each level of the tree doubles the length of the sorted runs and halves their count, so only log n levels of merging are needed.",
      "label": "Merge-sort level",
      "states": [
        "initial sequence",
        "merge to pairs",
        "merge to runs of 4",
        "final merge",
        "sorted"
      ],
      "default": "initial sequence"
    },
    {
      "id": "stabilityTrace",
      "type": "toggle",
      "teaches": "That stability is a property of the comparison inside merge, not of the final sorted values — the two equal 2s are distinguishable and keep their original relative order.",
      "label": "Track duplicate 2s (stability trace)",
      "default": false
    }
  ],
  "demo_steps": [
    {
      "title": "Eight one-element runs",
      "narration": "The bottom rank shows the input 5 2 4 7 1 3 2 6 as eight single-element boxes. A one-element sequence is already sorted, so every one of these is a valid sorted run.",
      "state": {
        "mergeLevel": "initial sequence",
        "stabilityTrace": false
      }
    },
    {
      "title": "First merge pass: runs of 2",
      "narration": "Adjacent singletons are merged pairwise into 2 5, 4 7, 1 3 and 2 6. Four merges, each a single comparison — the boxes get twice as wide and half as numerous.",
      "state": {
        "mergeLevel": "merge to pairs",
        "stabilityTrace": false
      }
    },
    {
      "title": "Second pass: runs of 4",
      "narration": "Two merges combine the pairs into 2 4 5 7 and 1 2 3 6. Watch the cursors: each merge is one left-to-right sweep, never a rescan.",
      "state": {
        "mergeLevel": "merge to runs of 4",
        "stabilityTrace": false
      }
    },
    {
      "title": "Write merge() for the final pair",
      "narration": "Now implement merge(left, right) yourself on 2 4 5 7 and 1 2 3 6. Each take() appends one value to the top box, and the replay shows exactly which comparison caused it.",
      "state": {
        "mergeLevel": "final merge",
        "stabilityTrace": false
      }
    },
    {
      "title": "Ties and stability",
      "narration": "Turn on the duplicate trace: the two 2s are tinted differently. With '<=' the left 2 goes first and order is preserved; swap to strict '<' in the buggy version and the duplicates silently swap places.",
      "state": {
        "mergeLevel": "final merge",
        "stabilityTrace": true
      }
    },
    {
      "title": "Sorted sequence",
      "narration": "The top box reads 1 2 2 3 4 5 6 7. Three levels of merging over eight elements — log n passes, each touching every element once, giving n log n work.",
      "state": {
        "mergeLevel": "sorted",
        "stabilityTrace": true
      }
    }
  ],
  "keyInsight": "Merging is cheap because both inputs are already sorted — you only ever compare the two front elements — so the entire cost of merge sort is n comparisons per level times log n levels.",
  "reconstructionNotes": "Four ranks stacked bottom-to-top on a white background, all boxes light gray with thin black borders and serif numerals. Bottom rank: eight small equal squares (5, 2, 4, 7, 1, 3, 2, 6) evenly spread across the full width, with the caption 'initial sequence' centered below. Third rank: four boxes of double width ('2 5', '4 7', '1 3', '2 6'), each centered above its two children. Second rank: two boxes of quadruple width ('2 4 5 7' on the left, '1 2 3 6' on the right). Top rank: one very wide box '1 2 2 3 4 5 6 7' centered, caption 'sorted sequence' above it. Every parent receives two thick medium-gray arrows angling up-inward from its two children, with the word 'merge' in serif text centered between each arrow pair. Box width should visibly double from rank to rank while box count halves — that geometric relationship is the point of the figure. For the interactive layer: the active merge highlights its two source boxes, its arrow pair, and the destination box with a saturated accent outline (e.g. blue), dims the rest of the tree, and draws small cursor triangles under the front element of each source run; the destination box fills slot by slot as take() fires. When the stability trace is on, tint the 2 originating in the left half one color (e.g. orange) and the 2 originating in the right half another (e.g. teal) and carry those tints all the way up into the final box."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

Here is the generated code to evaluate:

