// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var ACC = '#1668c4';
var GRAY = '#808080';
var BOXFILL = '#d9d9d9';
var TINT_L = '#f2a65a';
var TINT_R = '#57c4bb';
var W = 720, H = 548;

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

function c(v, tag) { return { v: v, tag: tag || null }; }

var SING = [46, 132, 224, 310, 410, 496, 588, 674];
var BOT = [c(5), c(2, 'L'), c(4), c(7), c(1), c(3), c(2, 'R'), c(6)];

var RANKS = [
  {
    y: 38, h: 46, boxW: 452, fs: 22,
    boxes: [{ cx: 360, cells: [c(1), c(2, 'L'), c(2, 'R'), c(3), c(4), c(5), c(6), c(7)] }]
  },
  {
    y: 176, h: 46, boxW: 226, fs: 22,
    boxes: [{ cx: 178, cells: [c(2, 'L'), c(4), c(5), c(7)] }, { cx: 542, cells: [c(1), c(2, 'R'), c(3), c(6)] }]
  },
  {
    y: 310, h: 46, boxW: 113, fs: 22,
    boxes: [{ cx: 89, cells: [c(2, 'L'), c(5)] }, { cx: 267, cells: [c(4), c(7)] },
    { cx: 453, cells: [c(1), c(3)] }, { cx: 631, cells: [c(2, 'R'), c(6)] }]
  },
  {
    y: 434, h: 44, boxW: 42, fs: 22,
    boxes: SING.map(function (x, i) { return { cx: x, cells: [BOT[i]] }; })
  }
];

var MERGE_FS = [20, 19, 16];   /* per parent rank index 0,1,2 */

var LEVELS = ['initial sequence', 'merge to pairs', 'merge to runs of 4', 'final merge', 'sorted'];

var S = { level: 4, stability: false, frames: [], fi: 0, bad: [], stepIdx: -1, running: false };

/* ---------- drawing helpers ---------- */
function halo(t) { t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' }); return t; }

function arrow(x1, y1, x2, y2, color, wdt, op) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  var hl = wdt * 3.0, hw = wdt * 1.9;
  var bx = x2 - Math.cos(a) * hl, by = y2 - Math.sin(a) * hl;
  draw.line(x1, y1, bx, by).stroke({ color: color, width: wdt, linecap: 'butt' }).opacity(op);
  draw.polygon([[x2, y2],
  [bx - Math.sin(a) * hw, by + Math.cos(a) * hw],
  [bx + Math.sin(a) * hw, by - Math.cos(a) * hw]]).fill(color).opacity(op);
}

function drawBox(cx, y, w, h, cells, o) {
  o = o || {};
  var g = draw.group();
  var x0 = cx - w / 2;
  g.rect(w, h).move(x0, y).fill(o.fill || BOXFILL)
    .stroke({ color: o.accent ? ACC : '#333', width: o.accent ? 3 : 1.4 });
  var n = Math.max(1, cells.length);
  var cw = w / n;
  for (var k = 0; k < n; k++) {
    var cell = cells[k];
    var ccx = x0 + (k + 0.5) * cw;
    var sw = Math.max(14, Math.min(cw - 6, 34));
    if (!cell) {
      g.rect(sw, h - 14).move(ccx - sw / 2, y + 7).fill('#ffffff').opacity(0.8)
        .stroke({ color: '#b5b5b5', width: 1, dasharray: '3,3' });
      continue;
    }
    if (S.stability && cell.tag) {
      g.rect(sw, h - 12).radius(5).move(ccx - sw / 2, y + 6)
        .fill(cell.tag === 'L' ? TINT_L : TINT_R).opacity(0.9);
    }
    if (cell.hl || cell.bad) {
      g.rect(sw + 6, h - 5).radius(5).move(ccx - (sw + 6) / 2, y + 2.5).fill('none')
        .stroke({ color: cell.bad ? '#c62828' : ACC, width: 2.8 });
    }
    var t = g.text(String(cell.v))
      .font({ family: SERIF, size: o.fs || 22, anchor: 'middle' }).fill('#111').leading(1);
    t.center(ccx, y + h / 2);
    if (cell.faded) t.opacity(0.28);
  }
  g.opacity(o.opacity == null ? 1 : o.opacity);
  if (o.tip) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(o.tip, e); }).on('mouseleave', hideTooltip);
    if (o.pop) g.on('click', function () { showPopup(o.pop[0], o.pop[1]); });
  }
  return g;
}

function cursorTri(x, y) {
  draw.polygon([[x, y], [x - 7, y + 11], [x + 7, y + 11]]).fill(ACC);
}

function legend(showTints) {
  var x = 14, y = 18, dy = 17, fs = 12;
  function row(yy, swatch, label) {
    if (swatch === 'gray') draw.rect(17, 12).move(x, yy - 6).fill(BOXFILL).stroke({ color: '#333', width: 1 });
    else if (swatch === 'acc') draw.rect(17, 12).move(x, yy - 6).fill('#fff').stroke({ color: ACC, width: 2.4 });
    else {
      draw.rect(8, 12).move(x, yy - 6).fill(TINT_L);
      draw.rect(8, 12).move(x + 9, yy - 6).fill(TINT_R);
    }
    halo(draw.text(label).font({ family: 'sans-serif', size: fs, anchor: 'start' }).fill('#444').leading(1))
      .move(x + 23, yy - 7);
  }
  row(y, 'gray', 'sorted run');
  row(y + dy, 'acc', 'active merge');
  if (showTints) row(y + 2 * dy, 'tint', 'tracked duplicates');
}

/* ---------- main render ---------- */
function replayActive() { return S.frames.length > 0 && S.level >= 3; }

function render() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');

  var Lv = S.level;
  var act = (Lv >= 1 && Lv <= 3) ? Lv : 0;
  var dim = act ? 0.32 : 1;
  var fr = replayActive() ? S.frames[S.fi] : null;

  /* arrows + merge labels */
  for (var r = 2; r >= 0; r--) {
    var lev = 3 - r;
    if (Lv < lev) continue;
    var isAct = (lev === act);
    var parents = RANKS[r], children = RANKS[r + 1];
    for (var p = 0; p < parents.boxes.length; p++) {
      var P = parents.boxes[p];
      for (var s = 0; s < 2; s++) {
        var C = children.boxes[2 * p + s];
        var side = (s === 0) ? -1 : 1;
        var sx = C.cx + side * children.boxW * 0.15;
        var sy = children.y - 10;
        var ex = P.cx + side * parents.boxW * 0.19;
        var ey = parents.y + parents.h + 12;
        arrow(sx, sy, ex, ey, isAct ? ACC : GRAY, 5, isAct ? 1 : dim);
      }
      var my = (parents.y + parents.h + children.y) / 2;
      var tx = draw.text('merge').font({ family: SERIF, size: MERGE_FS[r], anchor: 'middle' })
        .fill(isAct ? ACC : '#111').leading(1);
      halo(tx); tx.center(P.cx, my); tx.opacity(isAct ? 1 : dim);
      tx.css('cursor', 'pointer');
      (function (len) {
        tx.on('mousemove', function (e) {
          showTooltip('merge two sorted runs of ' + len + ' → one sorted run of ' + (2 * len) +
            ' (one linear scan, at most ' + (2 * len - 1) + ' comparisons)', e);
        }).on('mouseleave', hideTooltip)
          .on('click', function () {
            showPopup('Why merging is cheap',
              'Both inputs are already sorted, so the next output value can only be the front of one run or the front of the other — a single comparison decides it. ' +
              'Each level of the tree therefore costs about n comparisons, and there are only log₂ n levels: n log n in total.');
          });
      })(RANKS[r + 1].boxes[2 * p].cells.length);
    }
  }

  /* boxes */
  for (var rr = 3; rr >= 0; rr--) {
    var rank = RANKS[rr];
    var rlev = 3 - rr;
    var visible = (rr === 3) || (Lv >= rlev);
    var involved = act && (rr === 3 - act || rr === 4 - act);
    var op = !act ? 1 : (involved ? 1 : dim);
    for (var b = 0; b < rank.boxes.length; b++) {
      var B = rank.boxes[b];
      if (!visible) {
        draw.rect(rank.boxW, rank.h).move(B.cx - rank.boxW / 2, rank.y).fill('none')
          .stroke({ color: '#cfcfcf', width: 1, dasharray: '4,4' }).opacity(0.7);
        continue;
      }
      var cells = B.cells.map(function (x) { return { v: x.v, tag: x.tag }; });
      var fill = BOXFILL;

      if (rr === 1 && fr) {
        var st = fr.state;
        var src = (b === 0) ? st.left : st.right;
        var cur = (b === 0) ? st.i : st.j;
        var hi = (b === 0) ? fr.indices.left : fr.indices.right;
        cells = src.map(function (x, k) {
          return { v: x.v, tag: x.tag, faded: k < cur, hl: (hi === k) };
        });
      }
      if (rr === 0) {
        if (fr) {
          var tot = fr.state.left.length + fr.state.right.length;
          cells = [];
          for (var k0 = 0; k0 < tot; k0++) {
            var oc = fr.state.out[k0];
            var isBad = (S.fi === S.frames.length - 1) && S.bad.indexOf(k0) >= 0;
            cells.push(oc ? { v: oc.v, tag: oc.tag, hl: (fr.indices.out === k0), bad: isBad } : null);
          }
          if (fr.state.out.length < tot) fill = '#ececec';
        } else if (Lv >= 4) {
          /* complete sorted sequence */
        } else {
          cells = [null, null, null, null, null, null, null, null];
          fill = '#ececec';
        }
      }

      var tip = (rr === 3) ? 'a single element is already a sorted run of length 1'
        : 'sorted run of length ' + cells.length;
      var pop = null;
      if (rr === 0) pop = ['The sorted sequence',
        'Eight elements, three merge passes: 1→2→4→8. Each pass sweeps every element exactly once, so the total work is n·log₂n = 8·3 = 24 element moves.'];
      drawBox(B.cx, rank.y, rank.boxW, rank.h, cells,
        {
          opacity: op, accent: !!involved && (rr === 3 - act), fill: fill,
          tip: tip, pop: pop, fs: rank.fs
        });

      /* cursors under the two source runs during replay */
      if (rr === 1 && fr) {
        var st2 = fr.state;
        var run = (b === 0) ? st2.left : st2.right;
        var cu = (b === 0) ? st2.i : st2.j;
        if (cu < run.length) {
          var x0 = B.cx - rank.boxW / 2;
          cursorTri(x0 + (cu + 0.5) * rank.boxW / run.length, rank.y + rank.h + 4);
        }
      }
    }
  }

  /* captions */
  halo(draw.text('sorted sequence').font({ family: SERIF, size: 24, anchor: 'middle' }).fill('#111').leading(1))
    .center(360, 19);
  halo(draw.text('initial sequence').font({ family: SERIF, size: 24, anchor: 'middle' }).fill('#111').leading(1))
    .center(360, 502);

  /* comparison readout — own strip at the very bottom, clear of the 'merge' labels */
  if (fr) {
    var msg = fr.message.length > 66 ? fr.message.slice(0, 65) + '…' : fr.message;
    halo(draw.text(msg).font({ family: SERIF, size: 15, anchor: 'middle' })
      .fill(fr.kind === 'error' ? '#c62828' : '#123').leading(1)).center(360, 533);
  }

  if (S.stability || act || fr) legend(S.stability);
}

/* ---------- state controls ---------- */
function setLevelIdx(i) {
  S.level = i;
  var sel = document.getElementById('mergeLevelInput');
  if (sel) sel.selectedIndex = i;
  render();
}
function setLevelByName(v) { setLevelIdx(Math.max(0, LEVELS.indexOf(v))); }
function toggle_stabilityTrace(on) {
  S.stability = !!on;
  var cb = document.getElementById('stabilityTraceInput');
  if (cb) cb.checked = !!on;
  render();
}

/* ---------- demo steps ---------- */
var DEMO = [
  { t: 'Eight one-element runs', n: 'The bottom rank shows 5 2 4 7 1 3 2 6 as eight single-element boxes. A one-element sequence is already sorted, so each is a valid sorted run.', s: { l: 'initial sequence', st: false } },
  { t: 'First pass: runs of 2', n: 'Adjacent singletons merge pairwise into 2 5, 4 7, 1 3 and 2 6. Four merges, one comparison each — boxes twice as wide, half as many.', s: { l: 'merge to pairs', st: false } },
  { t: 'Second pass: runs of 4', n: 'Two merges combine the pairs into 2 4 5 7 and 1 2 3 6. Each merge is one left-to-right sweep, never a rescan.', s: { l: 'merge to runs of 4', st: false } },
  { t: 'Write merge() yourself', n: 'Implement merge(left, right) on 2 4 5 7 and 1 2 3 6. Each take() fills one slot of the top box and the replay shows which comparison caused it.', s: { l: 'final merge', st: false } },
  { t: 'Ties and stability', n: 'The duplicate 2s are tinted. With <= the left 2 goes first and order is preserved; run the Buggy tab (strict <) and the duplicates silently swap.', s: { l: 'final merge', st: true } },
  { t: 'Sorted sequence', n: 'The top box reads 1 2 2 3 4 5 6 7. Three levels over eight elements — log n passes, each touching every element once: n log n work.', s: { l: 'sorted', st: true } }
];

function applyStep(k) {
  S.stepIdx = k;
  var nar = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (k < 0) {
    toggle_stabilityTrace(false);
    setLevelIdx(4);
    nar.textContent = 'The complete merge-sort tree: eight singletons at the bottom, merged pairwise upward into one sorted sequence. Press ▶ to walk it level by level.';
    lab.textContent = 'overview';
  } else {
    var d = DEMO[k];
    toggle_stabilityTrace(d.s.st);
    setLevelByName(d.s.l);
    nar.textContent = d.t + ' — ' + d.n;
    lab.textContent = (k + 1) + ' / ' + DEMO.length;
  }
}
function nextStep() { applyStep(Math.min(DEMO.length - 1, S.stepIdx + 1)); }
function prevStep() { applyStep(Math.max(-1, S.stepIdx - 1)); }

/* ---------- code samples ---------- */
var SAMPLES = {
  sample: 'function merge(left, right) {\n  // walk both runs, always taking the smaller front\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    if (frontLessEqual(left, right)) {\n      take(left);   // ties go LEFT -> stable\n    } else {\n      take(right);\n    }\n  }\n  // one run is exhausted; drain the other\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}',
  buggy: 'function merge(left, right) {\n  while (remaining(left) > 0 && remaining(right) > 0) {\n    // BUG: strict \'<\' sends TIES to the right run,\n    // so the 2 from the right half jumps ahead of the left 2.\n    if (front(left) < front(right)) {\n      take(left);\n    } else {\n      take(right);\n    }\n  }\n  while (remaining(left) > 0) take(left);\n  while (remaining(right) > 0) take(right);\n}',
  starter: 'function merge(left, right) {\n  // Your turn.\n  // remaining(run) front(run) frontLessEqual(a,b) take(run) note(text)\n  // Append every element of both runs, smallest first.\n\n}'
};
function loadSample(which) {
