/* ---------- worker ---------- */
var WORKER_SRC = `
self.onmessage = function(ev){
  var d = ev.data;
  var L = d.left, R = d.right;
  var i = 0, j = 0, out = [];
  var frames = [], ops = 0, t0 = Date.now();
  var CAP_OPS = 800, CAP_FRAMES = 1200, CAP_MS = 1500;
  function copy(a){ var r=[],k; for(k=0;k<a.length;k++) r.push({v:a[k].v, tag:a[k].tag, side:a[k].side||null}); return r; }
  function snap(){ return { left: copy(L), right: copy(R), i:i, j:j, out: copy(out) }; }
  function push(kind, idx, msg){
    frames.push({ kind:kind, state:snap(), indices:idx||{}, message:msg });
    if (frames.length > CAP_FRAMES){ throw new Error('Frame cap reached (' + CAP_FRAMES + ') - is your loop terminating?'); }
  }
  function guard(){
    ops++;
    if (ops > CAP_OPS){ throw new Error('Operation cap reached (' + CAP_OPS + ') - your loop probably never ends.'); }
    if (Date.now() - t0 > CAP_MS){ throw new Error('Timed out after ' + CAP_MS + 'ms - infinite loop?'); }
  }
  function nameOf(r){
    if (r === 'left') return 'left';
    if (r === 'right') return 'right';
    throw new Error('Unknown run ' + JSON.stringify(r) + ' - pass the merge() parameters, e.g. remaining(left).');
  }
  function arrOf(n){ return n === 'left' ? L : R; }
  function curOf(n){ return n === 'left' ? i : j; }
  function remaining(r){
    var n = nameOf(r); guard();
    var v = arrOf(n).length - curOf(n);
    push('remaining', {}, 'remaining(' + n + ') = ' + v);
    return v;
  }
  function front(r){
    var n = nameOf(r); guard();
    var a = arrOf(n), cc = curOf(n);
    if (cc >= a.length) throw new Error('front(' + n + ') but that run is exhausted - check remaining() first.');
    push('front', n === 'left' ? {left:cc} : {right:cc}, 'front(' + n + ') = ' + a[cc].v);
    return a[cc].v;
  }
  function frontLessEqual(x, y){
    var a = nameOf(x), b = nameOf(y); guard();
    var aa = arrOf(a), bb = arrOf(b), ca = curOf(a), cb = curOf(b);
    if (ca >= aa.length || cb >= bb.length) throw new Error('frontLessEqual() on an exhausted run - check remaining() first.');
    var res = aa[ca].v <= bb[cb].v;
    push('compare', {left:i, right:j},
      'front(' + a + ')=' + aa[ca].v + ' vs front(' + b + ')=' + bb[cb].v + ' -> ' + res + ' (take ' + (res ? a : b) + ')');
    return res;
  }
  function take(r){
    var n = nameOf(r); guard();
    var a = arrOf(n), cc = curOf(n);
    if (cc >= a.length) throw new Error('take(' + n + ') but that run is exhausted - check remaining() first.');
    var cell = a[cc];
    if (n === 'left') i++; else j++;
    out.push({ v: cell.v, tag: cell.tag, side: n });
    push('take', n === 'left' ? {left:cc, out:out.length-1} : {right:cc, out:out.length-1},
      'take(' + n + ') -> append ' + cell.v + ' to output slot ' + out.length);
    return cell.v;
  }
  function note(t){ guard(); push('note', {}, 'note: ' + String(t)); }

  try {
    push('start', {left:0, right:0},
      'start: left = [' + L.map(function(x){return x.v;}).join(', ') + '], right = [' + R.map(function(x){return x.v;}).join(', ') + ']');
    var factory;
    try {
      factory = new Function('remaining','front','frontLessEqual','take','note',
        '"use strict";' + d.code + '\\nreturn typeof merge === "function" ? merge : null;');
    } catch(se){ throw new Error('Syntax error: ' + se.message); }
    var fn = factory(remaining, front, frontLessEqual, take, note);
    if (!fn) throw new Error('No function named merge(left, right) was found - the entry point must be called merge.');
    fn('left','right');
    push('done', {}, 'merge() returned - output holds ' + out.length + ' of ' + (L.length + R.length) + ' elements.');
    self.postMessage({ frames: frames });
  } catch(err){
    frames.push({ kind:'error', state: snap(), indices:{}, message: 'ERROR: ' + ((err && err.message) ? err.message : String(err)) });
    self.postMessage({ frames: frames, error: ((err && err.message) ? err.message : String(err)) });
  }
};
`;

function parseRuns(s) {
  var parts = String(s).split('|');
  function nums(t) {
    t = String(t || '').replace(/^[^=]*=/, '');
    return t.split(/[,;\s]+/).filter(function (x) { return x.length; }).map(Number).filter(function (x) { return isFinite(x); });
  }
  var l = nums(parts[0]), r = nums(parts[1]);
  if (!l.length || !r.length) throw new Error('Enter two runs, e.g. "left = 2, 4, 5, 7 | right = 1, 2, 3, 6"');
  var shared = {};
  l.forEach(function (v) { if (r.indexOf(v) >= 0) shared[v] = 1; });
  return {
    left: l.map(function (v) { return { v: v, tag: shared[v] ? 'L' : null }; }),
    right: r.map(function (v) { return { v: v, tag: shared[v] ? 'R' : null }; })
  };
}

function checkSuccess(frames, runs) {
  var last = frames[frames.length - 1];
  if (last.kind === 'error') return { ok: false, msg: '⚠ error — see caption', bad: [] };
  var out = last.state.out, total = runs.left.length + runs.right.length;
  if (out.length !== total)
    return { ok: false, msg: '✗ output holds ' + out.length + ' of ' + total + ' — some values never taken', bad: [] };
  var bad = [], k;
  for (k = 1; k < out.length; k++) if (out[k].v < out[k - 1].v) { bad.push(k - 1, k); }
  if (bad.length) return { ok: false, msg: '✗ output is not non-decreasing', bad: bad };
  for (k = 1; k < out.length; k++)
    if (out[k].v === out[k - 1].v && out[k - 1].side === 'right' && out[k].side === 'left') bad.push(k - 1, k);
  if (bad.length) return { ok: false, msg: '✗ sorted but NOT stable — a right-run key jumped ahead of an equal left-run key (strict < instead of <=)', bad: bad };
  return { ok: true, msg: '✓ correct — complete, non-decreasing, ties kept left-before-right (stable)', bad: [] };
}

function setStatus(txt, color) {
  var el = document.getElementById('runStatus');
  el.textContent = txt;
  el.style.color = color || '#333';
}

function runCode() {
  if (S.running) return;
  pbStop();
  var runs;
  try { runs = parseRuns(document.getElementById('mergeCodeInput').value); }
  catch (e) { setStatus(e.message, '#c62828'); return; }
  var code = document.getElementById('mergeCodeCode').value;
  S.running = true;
  document.getElementById('runBtn').disabled = true;
  setStatus('running…', '#555');
  if (S.level < 3) setLevelIdx(3);

  var url, w;
  try {
    url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'application/javascript' }));
    w = new Worker(url);
  } catch (e) {
    S.running = false;
    document.getElementById('runBtn').disabled = false;
    setStatus('⚠ cannot start sandbox worker', '#c62828');
    return;
  }
  w.postMessage({ left: runs.left, right: runs.right, code: code });
  var done = false;
  var to = setTimeout(function () {
    if (done) return;
    done = true; w.terminate(); URL.revokeObjectURL(url);
    finishRun([{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: timed out — worker killed after 2.5 s (infinite loop?)' }], runs);
  }, 2500);
  w.onmessage = function (ev) {
    if (done) return;
    done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(ev.data.frames || [], runs);
  };
  w.onerror = function (ev) {
    if (done) return;
    done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun([{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: ' + (ev.message || 'worker failed') }], runs);
  };
}

function finishRun(frames, runs) {
  S.running = false;
  document.getElementById('runBtn').disabled = false;
  S.frames = frames.length ? frames : [{ kind: 'error', state: { left: runs.left, right: runs.right, i: 0, j: 0, out: [] }, indices: {}, message: 'ERROR: no frames produced' }];
  var res = checkSuccess(S.frames, runs);
  S.bad = res.bad;
  setStatus(res.msg, res.ok ? '#1b7a2f' : '#c62828');
  if (!res.ok && res.bad.length) toggle_stabilityTrace(true);
  document.getElementById('traceLog').value = S.frames.map(function (f, k) { return (k + 1) + '. ' + f.message; }).join('\n');
  S.fi = 0;
  updatePlayback();
  render();
}

/* ---------- playback ---------- */
var playTimer = null, speed = 1;
function update_speed(v) { speed = v; if (playTimer) { pbStop(); pbPlay(); } }
function updatePlayback() {
  var n = S.frames.length;
  document.getElementById('frameCounter').textContent = n ? (S.fi + 1) + ' of ' + n : '0 of 0';
  document.getElementById('frameCaption').textContent = n ? S.frames[S.fi].message : '';
  var log = document.getElementById('traceLog');
  if (n && log.scrollHeight) log.scrollTop = Math.max(0, (S.fi / n) * log.scrollHeight - log.clientHeight / 2);
}
function setFrame(i) {
  if (!S.frames.length) return;
  S.fi = Math.max(0, Math.min(S.frames.length - 1, i));
  updatePlayback(); render();
}
function pbFirst() { pbStop(); setFrame(0); }
function pbPrev() { pbStop(); setFrame(S.fi - 1); }
function pbNext() { pbStop(); setFrame(S.fi + 1); }
function pbStop() {
  if (playTimer) { clearTimeout(playTimer); playTimer = null; }
  document.getElementById('playBtn').textContent = '▶';
}
function pbPlay() {
  if (playTimer) { pbStop(); return; }
  if (!S.frames.length) return;
  if (S.fi >= S.frames.length - 1) S.fi = 0;
  document.getElementById('playBtn').textContent = '❚❚';
  var tick = function () {
    if (S.fi >= S.frames.length - 1) { pbStop(); return; }
    setFrame(S.fi + 1);
    if (S.fi < S.frames.length - 1) playTimer = setTimeout(tick, 750 / speed);
    else pbStop();
  };
  playTimer = setTimeout(tick, 750 / speed);
}

